import asyncio
await asyncio.sleep(5)

# Write a script using sql.js (pure JS, no native deps)
sqljs_script = """
const initSqlJs = require('sql.js');
const fs = require('fs');
const crypto = require('crypto');

async function main() {
    const SQL = await initSqlJs();
    const fileBuffer = fs.readFileSync('/workspace/world.db');
    const db = new SQL.Database(fileBuffer);

    // Check tables
    const tables = db.exec("SELECT name FROM sqlite_master WHERE type='table' AND name LIKE 'ts_%'");
    console.log('Tables:', JSON.stringify(tables));

    // Check schema
    const schema = db.exec("PRAGMA table_info(ts_reminders)");
    console.log('Schema:', JSON.stringify(schema));

    // Insert reminder
    const uuid = crypto.randomUUID();
    const now = Date.now() / 1000;
    const oneWeek = now + 7 * 24 * 60 * 60;

    db.run(
        "INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude) VALUES (?, ?, ?, ?, ?, ?)",
        [uuid,
         'Double-check address change for maya.patel@example.com - verify new default address: 1847 Willow Creek Rd, Austin, TX 78702, USA is correct',
         now, oneWeek, null, null]
    );
    console.log('INSERTED:', uuid);

    // Verify
    const verify = db.exec("SELECT * FROM ts_reminders WHERE reminder_id = '" + uuid + "'");
    console.log('VERIFIED:', JSON.stringify(verify, null, 2));

    // Write back to file
    const data = db.export();
    const buffer = Buffer.from(data);
    fs.writeFileSync('/workspace/world.db', buffer);
    console.log('Database saved');

    db.close();
}

main().catch(e => console.error('ERROR:', e));
"""
