async function main() {
    const SQL = await initSqlJs();
    const fileBuffer = fs.readFileSync('/workspace/world.db');
    const db = new SQL.Database(fileBuffer);

    const result = db.exec("SELECT reminder_id, content, reminder_timestamp FROM ts_reminders ORDER BY creation_timestamp DESC LIMIT 3");
